 import React, { useState, useEffect } from 'react'
import { supabase } from '../lib/supabase'
import { Link } from 'react-router-dom'
import ReactionButtons from './ReactionButtons'
import CommentSection from './CommentSection'
import VerifiedBadge from './VerifiedBadge'
import FollowButton from './follow/FollowButton'

export default function PostCard({ post, onRefresh, currentUser }) {
    const [showComments, setShowComments] = useState(false)
    const [userReaction, setUserReaction] = useState(null)
    const [reactions, setReactions] = useState({
        like: 0,
        dislike: 0,
        laugh: 0,
        wow: 0,
        sad: 0,
        angry: 0
    })
    const [isLiking, setIsLiking] = useState(false)

    useEffect(() => {
        const getReactions = async () => {
            const { data } = await supabase
                .from('post_reactions')
                .select('type')
                .eq('post_id', post.id)

            if (data) {
                const counts = { like: 0, dislike: 0, laugh: 0, wow: 0, sad: 0, angry: 0 }
                data.forEach(r => {
                    if (counts.hasOwnProperty(r.type)) {
                        counts[r.type]++
                    }
                })
                setReactions(counts)
            }

            if (currentUser) {
                const { data: userReact } = await supabase
                    .from('post_reactions')
                    .select('type')
                    .eq('post_id', post.id)
                    .eq('user_id', currentUser.id)
                    .single()
                
                if (userReact) {
                    setUserReaction(userReact.type)
                }
            }
        }
        getReactions()
    }, [post.id, currentUser])

    const handleReaction = async (type) => {
        if (!currentUser) {
            alert('Please sign in to react')
            return
        }

        if (isLiking) return
        setIsLiking(true)

        try {
            if (userReaction === type) {
                await supabase
                    .from('post_reactions')
                    .delete()
                    .eq('post_id', post.id)
                    .eq('user_id', currentUser.id)

                setUserReaction(null)
                setReactions(prev => ({
                    ...prev,
                    [type]: Math.max(0, prev[type] - 1)
                }))
            } else {
                if (userReaction) {
                    await supabase
                        .from('post_reactions')
                        .delete()
                        .eq('post_id', post.id)
                        .eq('user_id', currentUser.id)

                    setReactions(prev => ({
                        ...prev,
                        [userReaction]: Math.max(0, prev[userReaction] - 1)
                    }))
                }

                await supabase
                    .from('post_reactions')
                    .insert({
                        post_id: post.id,
                        user_id: currentUser.id,
                        type: type
                    })

                setUserReaction(type)
                setReactions(prev => ({
                    ...prev,
                    [type]: prev[type] + 1
                }))
            }

            const total = Object.values(reactions).reduce((a, b) => a + b, 0) + (userReaction ? 0 : 1)
            await supabase
                .from('posts')
                .update({ likes_count: total })
                .eq('id', post.id)

            if (onRefresh) onRefresh()

        } catch (error) {
            console.error('Error reacting:', error)
        } finally {
            setIsLiking(false)
        }
    }

    const handleDelete = async () => {
        if (window.confirm('Are you sure you want to delete this post?')) {
            try {
                await supabase.from('posts').delete().eq('id', post.id)
                if (onRefresh) onRefresh()
            } catch (error) {
                console.error('Error deleting post:', error)
                alert('Failed to delete post')
            }
        }
    }

    return (
        <div className="bg-white rounded-xl shadow-md overflow-hidden">
            <div className="p-4 pb-2">
                <div className="flex items-center justify-between">
                    <Link to={`/profile/${post.profiles?.id}`} className="flex items-center gap-3 hover:opacity-80 flex-1">
                        <div className="w-10 h-10 bg-green-500 rounded-full flex items-center justify-center text-white font-bold">
                            {post.profiles?.username?.[0]?.toUpperCase() || 'U'}
                        </div>
                        <div>
                            <div className="font-semibold text-gray-800 flex items-center gap-1.5">
                                {post.profiles?.full_name || post.profiles?.username || 'Unknown'}
                                {post.profiles?.is_verified && <VerifiedBadge size="sm" />}
                            </div>
                            <div className="text-sm text-gray-500">
                                @{post.profiles?.username || 'user'} • {new Date(post.created_at).toLocaleDateString()} at {new Date(post.created_at).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                            </div>
                        </div>
                    </Link>
                    <div className="flex items-center gap-2">
                        {post.user_id && post.user_id !== currentUser?.id && (
                            <FollowButton 
                                userId={post.user_id} 
                                username={post.profiles?.username}
                                onFollowChange={onRefresh}
                            />
                        )}
                        {post.user_id === currentUser?.id && (
                            <button onClick={handleDelete} className="text-gray-400 hover:text-red-500 transition" aria-label="Delete post">🗑️</button>
                        )}
                    </div>
                </div>
            </div>

            <div className="px-4 pb-2">
                <p className="text-gray-800 whitespace-pre-wrap">{post.text}</p>
                {post.image && (
                    <img src={post.image} alt="Post image" className="mt-3 rounded-lg max-h-96 w-full object-contain bg-gray-100" loading="lazy" />
                )}
            </div>

            <div className="px-4 py-2 border-t border-gray-100">
                <div className="flex items-center justify-between text-sm text-gray-500">
                    <div className="flex items-center gap-1">
                        {Object.entries(reactions).filter(([_, count]) => count > 0).length > 0 ? (
                            <>
                                {reactions.like > 0 && <span>❤️</span>}
                                {reactions.laugh > 0 && <span>😂</span>}
                                {reactions.wow > 0 && <span>😮</span>}
                                {reactions.sad > 0 && <span>😢</span>}
                                {reactions.angry > 0 && <span>😡</span>}
                                <span className="ml-1">{Object.values(reactions).reduce((a, b) => a + b, 0)}</span>
                            </>
                        ) : (
                            <span>No reactions yet</span>
                        )}
                    </div>
                    <button onClick={() => setShowComments(!showComments)} className="hover:text-green-600 transition">
                        💬 {post.comments?.length || 0} comments
                    </button>
                </div>
            </div>

            <div className="px-4 py-2 border-t border-gray-100">
                <ReactionButtons onReact={handleReaction} userReaction={userReaction} reactions={reactions} />
            </div>

            {showComments && (
                <div className="px-4 py-3 border-t border-gray-100">
                    <CommentSection postId={post.id} comments={post.comments || []} onRefresh={onRefresh} currentUser={currentUser} />
                </div>
            )}
        </div>
    )
}
